import org.rabochaya.projects.*;import org.rabochaya.maptests.GeoTiffFixtures;import java.io.*;import java.nio.file.*;import java.util.*;
public final class GeoTiffTests {
 static int n;static void ck(boolean v){n++;if(!v)throw new AssertionError("GeoTIFF "+n);}interface Work{void run()throws Exception;}static void reject(Work w)throws Exception{boolean failed=false;try{w.run();}catch(IOException|IllegalArgumentException e){failed=true;}ck(failed);}
 static File write(Path d,String name,byte[] data)throws IOException{Path p=d.resolve(name);Files.write(p,data);return p.toFile();}
 public static void main(String[] args)throws Exception{Path dir=Files.createTempDirectory("geotiff-control-");try{
  for(boolean little:new boolean[]{true,false}){File f=write(dir,little?"little.tif":"big.tif",GeoTiffFixtures.image(little,4326,1,1,true));byte[] original=Files.readAllBytes(f.toPath());try(GeoTiffRaster r=new GeoTiffRaster(f)){ck(r.width==4&&r.height==4);ck(r.pixel(1,1)==0xff463c64);ck(r.pixel(0,0)==0);ck(r.pixel(2,2)==0x80786464);ck(r.color(2.015,.985)==0xff463c64);ck(r.color(2.045,.985)==0);ck(Math.abs(r.transform.west-2)<1e-12&&Math.abs(r.transform.east-2.04)<1e-12);ck(Math.abs(r.transform.south-.96)<1e-12&&Math.abs(r.transform.north-1)<1e-12);}ck(Arrays.equals(original,Files.readAllBytes(f.toPath())));}
  try(GeoTiffRaster r=new GeoTiffRaster(write(dir,"point.tif",GeoTiffFixtures.image(true,4326,2,1,false)))){ck(Math.abs(r.transform.west-1.995)<1e-12);ck(Math.abs(r.transform.north-1.005)<1e-12);ck(r.color(2.01,.99)==0xff463c64);}
  try(GeoTiffRaster r=new GeoTiffRaster(write(dir,"mercator.tif",GeoTiffFixtures.image(false,3857,1,1,false)))){double lon=150/GeoRasterTransform.RADIUS*180/Math.PI,lat=Math.toDegrees(Math.atan(Math.sinh(250/GeoRasterTransform.RADIUS)));ck(r.color(lon,lat)==0xff463c64);ck(r.modelColor(150,250)==0xff463c64);ck(Math.abs(r.transform.south)<1e-12);}
  byte[] base=GeoTiffFixtures.image(true,4326,1,1,false);for(int tag:new int[]{259,274,284}){final int t=tag;reject(()->{try(GeoTiffRaster r=new GeoTiffRaster(write(dir,"invalid-"+t+".tif",GeoTiffFixtures.scalar(base,t,2)))){}});}
  reject(()->{try(GeoTiffRaster r=new GeoTiffRaster(write(dir,"truncated.tif",Arrays.copyOf(base,base.length-1)))){}});reject(()->{try(GeoTiffRaster r=new GeoTiffRaster(write(dir,"offset.tif",GeoTiffFixtures.scalar(base,273,Integer.MAX_VALUE)))){}});reject(()->{try(GeoTiffRaster r=new GeoTiffRaster(write(dir,"large.tif",GeoTiffFixtures.scalar(base,256,20001)))){}});reject(()->{try(GeoTiffRaster r=new GeoTiffRaster(write(dir,"badcrs.tif",GeoTiffFixtures.image(true,9999,1,1,false)))){}});reject(()->{try(GeoTiffRaster r=new GeoTiffRaster(write(dir,"badpoint.tif",GeoTiffFixtures.image(true,4326,3,1,false)))){}});
  for(boolean little:new boolean[]{true,false})for(int predictor:new int[]{1,2}){byte[] zipped=GeoTiffFixtures.deflated(little,4326,1,true,predictor,13);File compressed=write(dir,"deflate-"+little+"-"+predictor+".tif",zipped);try(GeoTiffRaster r=new GeoTiffRaster(compressed)){ck(r.pixel(1,1)==0xff463c64);ck(r.pixel(0,0)==0);ck(r.pixel(2,2)==0x80786464);ck(r.pixel(3,12)==0xffaaf464);ck(r.pixel(1,0)==0xff461464);}ck(Arrays.equals(zipped,Files.readAllBytes(compressed.toPath())));try(GeoTiffRaster r=new GeoTiffRaster(write(dir,"legacy-deflate.tif",GeoTiffFixtures.scalar(zipped,259,32946)))){ck(r.pixel(1,1)==0xff463c64);}}
  for(int photo:new int[]{0,1})for(int compression:new int[]{1,8}){try(GeoTiffRaster r=new GeoTiffRaster(write(dir,"gray-"+photo+"-"+compression+".tif",GeoTiffFixtures.gray(true,photo,compression,compression==8?2:1)))){int value=photo==0?175:80;ck(r.pixel(1,1)==(0xff000000|value<<16|value<<8|value));ck(r.pixel(0,0)==0);value=photo==0?115:140;ck(r.pixel(2,2)==(0x80000000|value<<16|value<<8|value));ck(r.color(2.015,.985)==(0xff000000|(photo==0?175:80)*0x010101));}}
  byte[] zip=GeoTiffFixtures.deflated(true,4326,1,false,2,4),corrupt=zip.clone();corrupt[corrupt.length-1]^=1;reject(()->{try(GeoTiffRaster r=new GeoTiffRaster(write(dir,"checksum.tif",corrupt))){}});reject(()->{try(GeoTiffRaster r=new GeoTiffRaster(write(dir,"inflate-overflow.tif",GeoTiffFixtures.scalar(zip,256,2)))){}});reject(()->{try(GeoTiffRaster r=new GeoTiffRaster(write(dir,"inflate-short.tif",GeoTiffFixtures.scalar(zip,256,8)))){}});reject(()->{try(GeoTiffRaster r=new GeoTiffRaster(write(dir,"unsupported-predictor.tif",GeoTiffFixtures.scalar(zip,317,3)))){}});
  GeoRasterTransform flip=GeoRasterTransform.scale(4,4,4326,false,-.01,-.01,0,0,2,1);ck(flip.cell(1.985,1.015)==((long)1<<32|1));reject(()->new GeoRasterTransform(4,4,4326,false,1,1,0,1,1,0));ck(flip.cell(Double.NaN,0)==-1);double[] world=GeoRasterTransform.viewport(-180,-85,180,85,512,512);ck(world[0]==.5&&Math.abs(world[1]-.5)<1e-12&&world[2]<1);double[] wide=GeoRasterTransform.viewport(-170,-10,170,10,512,512);ck(wide[0]==.5&&wide[2]<1);double[] small=GeoRasterTransform.viewport(2,.96,2.04,1,800,600);ck(Math.abs(small[0]-(182.02/360))<1e-12&&small[2]>12);System.out.println("PASS GeoTIFF/transform: "+n+" assertions");
 }finally{try(java.util.stream.Stream<Path> paths=Files.walk(dir)){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(IOException e){throw new RuntimeException(e);}});}}}
}
